def longest_unique_run(pages):
    last_seen = {}
    start = 0
    best = 0
    for end, page in enumerate(pages):
        if page in last_seen and last_seen[page] >= start:
            start = last_seen[page] + 1
        last_seen[page] = end
        best = max(best, end - start + 1)
    return best
